const A = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";
function b58encode(buf){
  let n = 0n;
  for (const byte of buf) n = n*256n + BigInt(byte);
  let out = "";
  if (n === 0n) out = "";
  while (n > 0n){ out = A[Number(n % 58n)] + out; n = n / 58n; }
  let z = 0; while (z < buf.length && buf[z] === 0) z++;
  return A[0].repeat(z) + out;
}
function b58decodeStr(s){
  // rstrip python-style handled by caller
  let z = 0; while (z < s.length && s[z] === '1') z++;
  const body = s.slice(z);
  let n = 0n;
  for (const ch of body){ const i = A.indexOf(ch); if (i < 0) throw new Error("Invalid character '"+ch+"'"); n = n*58n + BigInt(i); }
  const bytes = [];
  while (n > 0n){ bytes.unshift(Number(n % 256n)); n = n/256n; }
  return Buffer.from(new Array(z).fill(0).concat(bytes));
}
function pyrepr(buf){
  const hasS = buf.includes(0x27), hasD = buf.includes(0x22);
  const q = (hasS && !hasD) ? '"' : "'";
  let s = "b" + q;
  for (const b of buf){
    if (b === 0x5c) s += "\\\\";
    else if (b === q.charCodeAt(0)) s += "\\" + q;
    else if (b === 0x09) s += "\\t";
    else if (b === 0x0a) s += "\\n";
    else if (b === 0x0d) s += "\\r";
    else if (b < 0x20 || b >= 0x7f) s += "\\x" + b.toString(16).padStart(2,"0");
    else s += String.fromCharCode(b);
  }
  return s + q;
}
module.exports = {A, b58encode, b58decodeStr, pyrepr};
if (require.main === module){
  const mode = process.argv[2];
  const arg = process.argv[3];
  if (mode === "enc") console.log(pyrepr(Buffer.from(b58encode(Buffer.from(arg,"utf8")),"ascii")));
  else if (mode === "dec") console.log(pyrepr(b58decodeStr(arg)));
}
